void	dijkstra(t_graph *g, int start)
{
	int	dist[g->n];
	int	visited[g->n];

	for (int i = 0; i < g->n; i++)
	{
		dist[i] = INT_MAX;
		visited[i] = 0;
	}
	dist[start] = 0;
	for (int count = 0; count < g->n - 1; count++)
	{
		int u = min_distance(dist, visited, g->n);
		visited[u] = 1;
		for (int v = 0; v < g->n; v++)
		{
			if (!visited[v] && g->adj[u][v] && dist[u] != INT_MAX && dist[u] + g->adj[u][v] < dist[v])
				dist[v] = dist[u] + g->adj[u][v];
		}
	}
}

void	dfs(int grid[R][C], int r, int c, int visited[R][C])
{
	if (r < 0 || c < 0 || r >= R || c >= C || grid[r][c] == 0 || visited[r][c])
		return ;
	visited[r][c] = 1;
	dfs(grid, r + 1, c, visited);
	dfs(grid, r - 1, c, visited);
	dfs(grid, r, c + 1, visited);
	dfs(grid, r, c - 1, visited);
}

void	flood_fill(int screen[M][N], int x, int y, int prevC, int newC)
{
	if (x < 0 || x >= M || y < 0 || y >= N || screen[x][y] != prevC)
		return ;
	screen[x][y] = newC;
	flood_fill(screen, x + 1, y, prevC, newC);
	flood_fill(screen, x - 1, y, prevC, newC);
	flood_fill(screen, x, y + 1, prevC, newC);
	flood_fill(screen, x, y - 1, prevC, newC);
}

t_node	*insert_avl(t_node *node, int key)
{
	if (!node)
		return (new_node(key));
	if (key < node->key)
		node->left = insert_avl(node->left, key);
	else if (key > node->key)
		node->right = insert_avl(node->right, key);
	else
		return (node);
	node->height = 1 + max(height(node->left), height(node->right));
	int balance = get_balance(node);
	if (balance > 1 && key < node->left->key)
		return (right_rotate(node));
	if (balance < -1 && key > node->right->key)
		return (left_rotate(node));
	return (node);
}

void	kmp_search(char *pat, char *txt)
{
	int m = strlen(pat);
	int n = strlen(txt);
	int lps[m];

	compute_lps(pat, m, lps);
	int i = 0, j = 0;
	while (i < n)
	{
		if (pat[j] == txt[i])
		{
			i++;
			j++;
		}
		if (j == m)
		{
			printf("Found pattern at %d", i - j);
			j = lps[j - 1];
		}
		else if (i < n && pat[j] != txt[i])
		{
			if (j != 0)
				j = lps[j - 1];
			else
				i++;
		}
	}
}

void	quick_sort(int *arr, int lo, int hi)
{
	if (lo < hi)
	{
		int pi = partition(arr, lo, hi);
		quick_sort(arr, lo, pi - 1);
		quick_sort(arr, pi + 1, hi);
	}
}

void	merge_sort(int *arr, int l, int r)
{
	if (l < r)
	{
		int m = l + (r - l) / 2;
		merge_sort(arr, l, m);
		merge_sort(arr, m + 1, r);
		merge(arr, l, m, r);
	}
}

void	trie_insert(t_trie *root, const char *key)
{
	t_trie *curr = root;

	while (*key)
	{
		int index = *key - 'a';
		if (!curr->children[index])
			curr->children[index] = new_trie_node();
		curr = curr->children[index];
		key++;
	}
	curr->is_end = 1;
}

int	binary_search_rec(int *arr, int l, int r, int x)
{
	if (r >= l)
	{
		int mid = l + (r - l) / 2;
		if (arr[mid] == x)
			return (mid);
		if (arr[mid] > x)
			return (binary_search_rec(arr, l, mid - 1, x));
		return (binary_search_rec(arr, mid + 1, r, x));
	}
	return (-1);
}

void	heapify(int *arr, int n, int i)
{
	int largest = i;
	int l = 2 * i + 1;
	int r = 2 * i + 2;

	if (l < n && arr[l] > arr[largest])
		largest = l;
	if (r < n && arr[r] > arr[largest])
		largest = r;
	if (largest != i)
	{
		int t = arr[i];
		arr[i] = arr[largest];
		arr[largest] = t;
		heapify(arr, n, largest);
	}
}
